const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => new Date().toISOString().slice(0,10);
const stamp = () => new Date().toISOString();
const year = new Date().getFullYear();
const listLike = ['Rare','Unlikely','Likely','Almost Certain','Certain'];
const listImpact = ['Insignificant','Minor','Moderate','Major','Catastrophic'];
const categories = ['Financial','Mandate & Governance','Customer','Internal Operations','Organisation Capacity'];
const divisions = ['Strategy','Technology','Operations','Finance','Human Capital','Procurement','Legal','Commercial','Ecosystem','Tenancy','Land','StratComm','Other'];
const controls = ['Satisfactory','Inefficiencies','Unsatisfactory','Not assessed'];
const statusList = ['Draft','Submitted','Under Review','Returned','Approved','Monitoring','Closed'];
const riskStatusLabel = s => s === 'Under Review' ? 'Under Review' : s;
const riskScore = (l,i) => (Number(l)||0)*(Number(i)||0);
function riskLevel(score){return score >= 20?'High':score >= 12?'Significant':score >= 5?'Moderate':'Low';}
const levelColour = {High:'#db5360',Significant:'#e99243',Moderate:'#e6b846',Low:'#35a77f'};
const humanDate = d => { if(!d) return '—'; const v = new Date(d.length===10?d+'T00:00:00':d);return Number.isNaN(v.getTime()) ? d : v.toLocaleDateString('en-MY',{day:'2-digit',month:'short',year:'numeric'});};
const initials = v => String(v||'MR').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
const fmt = v => String(v??'').replace(/\n/g,'\n');
const n = (v,defaultValue=1) => { const q=Number(v);return Number.isFinite(q)?q:defaultValue; };
const uid = () => globalThis.crypto?.randomUUID?.() || `x${Date.now().toString(36)}${Math.random().toString(36).slice(2,9)}`;
