const storageKey='mranti-riskhub-v1';
const state={view:'dashboard',role:'staff',user:demoStaff,risks:[],loading:false,backend:null,live:false,selectedId:null,editingId:null,draftActions:[],query:'',filterStatus:'',filterLevel:''};
function history(r,action,note=''){r.history=[...(r.history||[]),{at:stamp(),by:state.user.name,action,note}];r.updatedAt=stamp();}
function visible(){return state.role==='reviewer'?state.risks:state.risks.filter(r=>r.ownerUid===state.user.uid);}
function pending(){return state.risks.filter(r=>['Submitted','Under Review'].includes(r.status));}
function options(items,current,placeholder){return `${placeholder?`<option value="">${esc(placeholder)}</option>`:''}${items.map(item=>`<option value="${esc(item)}" ${String(current)===String(item)?'selected':''}>${esc(item)}</option>`).join('')}`;}
function scaleOptions(labels,current){return labels.map((x,i)=>`<option value="${i+1}" ${Number(current)===i+1?'selected':''}>${i+1} — ${esc(x)}</option>`).join('');}
function badge(text){return `<span class="pill p-${esc(String(text).replaceAll(' ','-'))}">${esc(text)}</span>`;}
const icon = name => {
 const defs={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',register:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',new:'<path d="M12 5v14M5 12h14"/>',approvals:'<path d="M9 12l2 2 4-4"/><rect x="3" y="3" width="18" height="18" rx="4"/>',actions:'<path d="M4 7h16M4 12h16M4 17h16"/><path d="M7 4v16"/>',matrix:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18M15 3v18M3 9h18M3 15h18"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.9 4.9L7 7M17 17l2.1 2.1M2 12h3M19 12h3M4.9 19.1L7 17M17 7l2.1-2.1"/>'};
 return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${defs[name]||defs.dashboard}</svg>`;
};
const navItems=[['dashboard','Overview','dashboard'],['register','Risk Register','register'],['new','Submit New Risk','new'],['approvals','Risk Approvals','approvals'],['actions','Action Tracker','actions'],['matrix','Risk Matrix','matrix'],['settings','Settings & Guide','settings']];
function nav(){const count=pending().length;$('#nav').innerHTML=navItems.filter(x=>x[0]!=='approvals'||state.role==='reviewer').map(([key,label,ico])=>`<button class="nav-item ${state.view===key?'active':''}" data-view="${key}">${icon(ico)}<span>${label}</span>${key==='approvals'&&count?`<span class="nav-counter">${count}</span>`:''}</button>`).join('');$('#breadcrumb').textContent=navItems.find(x=>x[0]===state.view)?.[1]||'Overview';$('#profileName').textContent=state.user?.name||'Guest';$('#profileRole').textContent=state.role==='reviewer'?'Risk Team Reviewer':'Risk Owner';$('#avatar').textContent=initials(state.user?.name||'Guest');$('#modePill').textContent=state.live?'LIVE / SECURED':'DEMO MODE';$('#modePill').classList.toggle('live',state.live);$('#footerMode').textContent=state.live?'Shared records subject to Firebase security rules.':'Demonstration data stored in this browser only.';}
function pageHead(tag,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(tag)}</div><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div>${action?`<div class="actions">${action}</div>`:''}</div>`;}
function btnNew(){return '<button class="btn primary" data-view="new">＋ Register New Risk</button>';}
function totalPending(list){return list.filter(r=>['Submitted','Under Review'].includes(r.status)).length;}
function summaryCards(list){const significant=list.filter(r=>['High','Significant'].includes(riskLevel(riskScore(r.residualLikelihood,r.residualImpact)))).length;const monitoring=list.filter(r=>['Approved','Monitoring'].includes(r.status)).length;const high=list.filter(r=>riskLevel(riskScore(r.residualLikelihood,r.residualImpact))==='High').length;return `<div class="kpi-grid"><div class="kpi"><div class="kpi-label">TOTAL REGISTERED RISKS</div><div class="kpi-value">${list.length}</div><span class="kpi-icon ic-blue">▤</span><div class="kpi-sub">Within your authorised view</div></div><div class="kpi"><div class="kpi-label">AWAITING VALIDATION</div><div class="kpi-value">${totalPending(list)}</div><span class="kpi-icon ic-gold">◴</span><div class="kpi-sub">Pending Risk Team decision</div></div><div class="kpi"><div class="kpi-label">HIGH & SIGNIFICANT</div><div class="kpi-value">${significant}</div><span class="kpi-icon ic-red">⚑</span><div class="kpi-sub">Residual risk assessment</div></div><div class="kpi"><div class="kpi-label">APPROVED / MONITORING</div><div class="kpi-value">${monitoring}</div><span class="kpi-icon ic-green">✓</span><div class="kpi-sub">Action plans being tracked</div></div></div>`;}
function table(list,limit=null){const items=limit?list.slice(0,limit):list;if(!items.length)return `<div class="empty"><div class="empty-icon">▤</div><strong>No risks found</strong><div>No risks match the current selection.</div></div>`;return `<div class="table-scroll"><table><thead><tr><th>Risk reference</th><th>Risk title</th><th>Division</th><th>Residual rating</th><th>Workflow status</th><th>Updated</th><th></th></tr></thead><tbody>${items.map(r=>{const s=riskScore(r.residualLikelihood,r.residualImpact);return `<tr><td class="ref">${esc(r.id)}</td><td><div class="risk-title" title="${esc(r.title)}">${esc(r.title)}</div><div class="dim">${esc(r.category)}</div></td><td>${esc(r.division)}<div class="dim">${esc(r.department)}</div></td><td>${badge(riskLevel(s))} <span style="font-size:10px">${s}</span></td><td>${badge(r.status)}</td><td>${humanDate(r.updatedAt)}</td><td><button class="link-button" data-risk="${esc(r.id)}">View →</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function dashboard(){const all=visible();const total=all.length;const dist=['High','Significant','Moderate','Low'].map(l=>({name:l,count:all.filter(r=>riskLevel(riskScore(r.residualLikelihood,r.residualImpact))===l).length}));let acc=0;const grad=dist.map(d=>{const start=acc;acc+=total?d.count/total*100:0;return `${levelColour[d.name]} ${start}% ${acc}%`;}).join(',');const byDiv=[...new Set(all.map(r=>r.division))].map(k=>({name:k,n:all.filter(r=>r.division===k).length})).sort((a,b)=>b.n-a.n).slice(0,6);return pageHead('Risk intelligence','Risk Management Overview','Enterprise-level visibility of registered risks and mitigation activities.',btnNew())+summaryCards(all)+`<div class="dashboard-columns"><section class="panel"><div class="panel-head"><div><h2>Residual Risk Distribution</h2><div class="minor">Based on the validated / latest risk assessment</div></div><span class="pill p-Low">${total} risks</span></div><div class="panel-body"><div class="donut-wrap"><div class="donut" style="background:${total?`conic-gradient(${grad})`:'#edf1f7'}"><div class="donut-hole"><strong>${total}</strong><span>REGISTERED</span></div></div><div class="legend">${dist.map(d=>`<div class="legend-item"><span><i class="dot" style="background:${levelColour[d.name]}"></i>${d.name}</span><b>${d.count}</b></div>`).join('')}</div></div></div></section><section class="panel"><div class="panel-head"><div><h2>Risks by Division</h2><div class="minor">Across the selected access scope</div></div></div><div class="panel-body"><div class="bar-list">${byDiv.length?byDiv.map(d=>`<div><div class="bar-label"><span>${esc(d.name)}</span><span>${d.n}</span></div><div class="bar-track"><div class="bar-value" style="width:${100*d.n/Math.max(1,...byDiv.map(x=>x.n))}%"></div></div></div>`).join(''):'<p class="subtitle">No data available.</p>'}</div></div></section></div><section class="panel"><div class="panel-head"><div><h2>Recent Risk Submissions</h2><div class="minor">Review status, severity and ownership</div></div><button class="btn small" data-view="register">View all risks →</button></div>${table([...all].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)),5)}</section><div class="overview-foot"><div class="insight"><strong>1 · Identify & assess</strong><span>Risk owners capture risk description, causes, impacts, controls and 5×5 scoring.</span></div><div class="insight"><strong>2 · Validate & approve</strong><span>Risk Team validates assessments and accepts or returns action plans.</span></div><div class="insight"><strong>3 · Treat & monitor</strong><span>Approved actions have accountable owners, target dates and status updates.</span></div></div>`;}
function register(){let all=visible().filter(r=>(!state.filterStatus||r.status===state.filterStatus)&&(!state.filterLevel||riskLevel(riskScore(r.residualLikelihood,r.residualImpact))===state.filterLevel)&&(!state.query||[r.title,r.id,r.division,r.department,r.category,r.ownerName].join(' ').toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return pageHead('Risk library','Risk Register','A consolidated view of risks, ownership, assessments and approval stages.',`<button class="btn" id="exportCsv">↧ Export CSV</button>${btnNew()}`)+`<section class="panel"><div class="table-toolbar"><div class="search"><input class="input" id="searchRisk" placeholder="Search risk, reference or owner..." value="${esc(state.query)}" aria-label="Search risks"/></div><select class="form-control" id="statusFilter" aria-label="Filter by status">${options(statusList,state.filterStatus,'All statuses')}</select><select class="form-control" id="levelFilter" aria-label="Filter by risk level">${options(['Low','Moderate','Significant','High'],state.filterLevel,'All risk levels')}</select><span class="dim">${all.length} records</span></div><div id="riskRows">${table(all)}</div></section>`;}
const emptyForm={title:'',category:'Internal Operations',division:'Strategy',department:'',ownerName:'',ownerEmail:'',description:'',rootCause:'',consequences:'',existingControls:'',controlEffectiveness:'Not assessed',response:'Reduce',inherentLikelihood:3,inherentImpact:3,residualLikelihood:2,residualImpact:2};
function actionsHTML(){return state.draftActions.map((a,i)=>`<div class="action-item-form" data-action-row="${i}"><div class="action-item-head"><span>Action ${i+1}</span>${state.draftActions.length>1?`<button type="button" class="link-button" data-remove-action="${i}">Remove</button>`:''}</div><div class="action-fields"><div class="field"><label>Proposed action / additional control <span class="required">*</span></label><textarea class="form-control" data-field="description" required placeholder="Describe what will be done">${esc(a.description)}</textarea></div><div class="field"><label>Action owner <span class="required">*</span></label><input class="form-control" data-field="owner" value="${esc(a.owner)}" required placeholder="e.g. Data Team"/></div><div class="field"><label>Target date <span class="required">*</span></label><input class="form-control" type="date" data-field="dueDate" value="${esc(a.dueDate)}" required/></div></div></div>`).join('');}
function formField(name,label,value,required=false,wide=false,textarea=false,help=''){return `<div class="field ${wide?'full':''}"><label for="f-${name}">${esc(label)} ${required?'<span class="required">*</span>':''}</label>${textarea?`<textarea class="form-control" id="f-${name}" name="${name}" ${required?'required':''} placeholder="Enter details...">${esc(value)}</textarea>`:`<input id="f-${name}" class="form-control" name="${name}" value="${esc(value)}" ${required?'required':''}/>`}${help?`<div class="hint">${esc(help)}</div>`:''}</div>`;}
function riskForm(){const r=state.editingId?state.risks.find(x=>x.id===state.editingId):null;const v={...emptyForm,...r};const title=state.editingId?'Revise Risk Submission':'Register New Risk';return pageHead('Risk identification',title,'Complete the information below and submit it for Risk Team validation.')+`<div class="form-shell"><div class="notice">Risk scoring uses MRANTI's own 5×5 likelihood and impact scale. The Risk Team can validate or return the submitted assessment.</div><form id="riskForm"><section class="panel form-section"><div class="section-title"><h2><span class="section-number">01</span>Risk Identification</h2></div><div class="form-grid">${formField('title','Risk title',v.title,true,true)}<div class="field"><label>Risk category <span class="required">*</span></label><select class="form-control" name="category">${options(categories,v.category)}</select></div><div class="field"><label>Division <span class="required">*</span></label><select class="form-control" name="division">${options(divisions,v.division)}</select></div>${formField('department','Department / Unit',v.department,true)}${formField('ownerName','Risk owner / PIC',v.ownerName||state.user.name,true)}${formField('description','Risk description',v.description,true,true,true)}${formField('rootCause','Root cause',v.rootCause,true,true,true)}${formField('consequences','Potential consequences',v.consequences,true,true,true)}</div></section><section class="panel form-section"><div class="section-title"><h2><span class="section-number">02</span>Risk Assessment</h2></div><div class="form-grid"><div class="field"><label>Inherent likelihood</label><select class="form-control" name="inherentLikelihood">${scaleOptions(listLike,v.inherentLikelihood)}</select></div><div class="field"><label>Inherent impact</label><select class="form-control" name="inherentImpact">${scaleOptions(listImpact,v.inherentImpact)}</select></div><div class="field full"><div id="inherentScore" class="score-card"></div></div><div class="field full"><label>Existing controls <span class="required">*</span></label><textarea class="form-control" name="existingControls" required>${esc(v.existingControls)}</textarea></div><div class="field"><label>Control effectiveness</label><select class="form-control" name="controlEffectiveness">${options(controls,v.controlEffectiveness)}</select></div><div class="field"><label>Risk response strategy</label><select class="form-control" name="response">${options(['Reduce','Transfer','Accept','Avoid'],v.response)}</select></div><div class="field"><label>Residual likelihood</label><select class="form-control" name="residualLikelihood">${scaleOptions(listLike,v.residualLikelihood)}</select></div><div class="field"><label>Residual impact</label><select class="form-control" name="residualImpact">${scaleOptions(listImpact,v.residualImpact)}</select></div><div class="field full"><div id="residualScore" class="score-card"></div></div></div></section><section class="panel form-section"><div class="section-title"><h2><span class="section-number">03</span>Proposed Action Plan</h2><button type="button" id="addAction" class="btn small">＋ Add Action</button></div><div style="padding:20px" id="actionRows">${actionsHTML()}</div></section><div class="form-actions"><button type="button" data-view="register" class="btn">Cancel</button><button type="submit" class="btn" value="Draft" name="saveType" formnovalidate>Save as Draft</button><button type="submit" class="btn primary" value="Submitted" name="saveType">Submit for Validation →</button></div></form></div>`;}
function riskScorePreview(){const form=$('#riskForm');if(!form)return;[['inherentLikelihood','inherentImpact','inherentScore','Inherent / gross risk'],['residualLikelihood','residualImpact','residualScore','Residual risk']].forEach(([l,i,id,name])=>{const s=riskScore(form.elements[l].value,form.elements[i].value);const level=riskLevel(s);$(`#${id}`).innerHTML=`<div><strong>${name}</strong><span>Likelihood × Impact = ${form.elements[l].value} × ${form.elements[i].value}</span></div><div><div class="score-number">${s}</div>${badge(level)}</div>`;});}
function syncActions(){ $$('#actionRows [data-action-row]').forEach(el=>{const i=Number(el.dataset.actionRow);if(!state.draftActions[i])return;['description','owner','dueDate'].forEach(k=>state.draftActions[i][k]=el.querySelector(`[data-field="${k}"]`)?.value||'');});}
function renderFormActions(){if($('#actionRows'))$('#actionRows').innerHTML=actionsHTML();}
function approvals(){const all=state.risks.filter(r=>['Submitted','Under Review'].includes(r.status));return pageHead('Governance & assurance','Risk Validation Queue','Review new risk submissions and approve, or return proposed action plans.')+`<div class="notice warning">Risk Team members should confirm risk ownership, inherent and residual scoring, existing controls, proposed actions and deadlines before approval.</div><div class="kpi-grid"><div class="kpi"><div class="kpi-label">PENDING REVIEW</div><div class="kpi-value">${all.length}</div><div class="kpi-sub">Submitted or in review</div></div><div class="kpi"><div class="kpi-label">NEW SUBMISSIONS</div><div class="kpi-value">${all.filter(r=>r.status==='Submitted').length}</div><div class="kpi-sub">Awaiting first validation</div></div><div class="kpi"><div class="kpi-label">IN REVIEW</div><div class="kpi-value">${all.filter(r=>r.status==='Under Review').length}</div><div class="kpi-sub">Under Risk Team review</div></div><div class="kpi"><div class="kpi-label">RETURNED</div><div class="kpi-value">${state.risks.filter(r=>r.status==='Returned').length}</div><div class="kpi-sub">Require staff amendment</div></div></div><section class="panel"><div class="panel-head"><div><h2>Approval Requests</h2><div class="minor">Open a risk to record validation and decision</div></div></div>${table(all)}</section>`;}
function actionTracker(){const actions=visible().flatMap(r=>(r.actions||[]).map(a=>({...a,risk:r})));const approved=actions.filter(a=>['Approved','Monitoring','Closed'].includes(a.risk.status));const overdue=approved.filter(a=>a.status!=='Completed'&&a.dueDate&&a.dueDate<today()).length;const done=approved.filter(a=>a.status==='Completed').length;return pageHead('Risk treatment','Action Plan Tracker','Monitor mitigation progress, action owners and due dates.',`<button class="btn" id="exportCsv">↧ Export Risks</button>`)+`<div class="kpi-grid"><div class="kpi"><div class="kpi-label">ALL PROPOSED ACTIONS</div><div class="kpi-value">${actions.length}</div></div><div class="kpi"><div class="kpi-label">APPROVED ACTIONS</div><div class="kpi-value">${approved.length}</div></div><div class="kpi"><div class="kpi-label">COMPLETED</div><div class="kpi-value">${done}</div></div><div class="kpi"><div class="kpi-label">OVERDUE</div><div class="kpi-value">${overdue}</div></div></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Risk reference</th><th>Action / additional control</th><th>Owner</th><th>Due date</th><th>Status</th><th>Progress</th><th></th></tr></thead><tbody>${actions.map(a=>`<tr><td class="ref">${esc(a.risk.id)}</td><td><div class="risk-title" title="${esc(a.description)}">${esc(a.description)}</div></td><td>${esc(a.owner)}</td><td>${humanDate(a.dueDate)}${a.dueDate&&a.dueDate<today()&&a.status!=='Completed'?'<div class="dim" style="color:#c44951">Overdue</div>':''}</td><td>${esc(a.status)}</td><td style="min-width:100px">${n(a.progress,0)}%<div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,n(a.progress,0)))}%"></div></div></td><td><button class="link-button" data-risk="${esc(a.risk.id)}">View →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No actions recorded.</td></tr>'}</tbody></table></div></section>`;}
function matrix(){const all=visible();const counts={};all.forEach(r=>{const key=`${r.residualLikelihood}-${r.residualImpact}`;counts[key]=(counts[key]||0)+1;});let cells='';for(let l=5;l>=1;l--){cells+=`<div class="matrix-axis">${l}</div>`;for(let i=1;i<=5;i++){const score=l*i,level=riskLevel(score).toLowerCase(),count=counts[`${l}-${i}`]||0;cells+=`<div class="matrix-cell ${level}" title="Likelihood ${l}, Impact ${i}, score ${score}"><span>${count}</span><small>${score} pts</small></div>`;}}cells+='<div class="matrix-axis"></div>'+Array.from({length:5},(_,i)=>`<div class="matrix-axis">${i+1}</div>`).join('');return pageHead('Risk analytics','5 × 5 Risk Matrix','MRANTI residual risk ratings plotted by likelihood and impact.')+`<div class="matrix-layout"><section class="panel"><div class="panel-head"><div><h2>Residual Risk Heatmap</h2><div class="minor">Rows: likelihood (5 → 1) · Columns: impact (1 → 5)</div></div></div><div class="matrix-grid">${cells}</div><div style="font-size:11px;color:#8191a7;text-align:center;padding:0 10px 22px">Impact → Insignificant to Catastrophic</div></section><section class="panel"><div class="panel-head"><div><h2>Risk Classification</h2><div class="minor">As defined in your Risk Assessment Guide</div></div></div><div class="panel-body"><div class="matrix-summary">${[['High','20–25'],['Significant','12–16'],['Moderate','5–10'],['Low','1–4']].map(([k,t])=>`<div class="review-stat"><span>${badge(k)}</span><strong>${t}</strong></div>`).join('')}</div><p class="matrix-meta" style="margin-top:25px"><strong>Calculation</strong><br>Likelihood × Impact<br><br><strong>Likelihood</strong><br>1 Rare · 2 Unlikely · 3 Likely · 4 Almost Certain · 5 Certain<br><br><strong>Impact</strong><br>1 Insignificant · 2 Minor · 3 Moderate · 4 Major · 5 Catastrophic</p></div></section></div>`;}
function settings(){return pageHead('Configuration','Settings & User Guide','Understand how roles, security and risk ratings work.')+`<div class="dashboard-columns" style="grid-template-columns:1.2fr 1fr"><section class="panel"><div class="panel-head"><h2>Access & Environment</h2></div><div class="panel-body"><div class="setting-row"><div><strong>Application environment</strong><span>${state.live?'Firebase Auth + Cloud Firestore':'Browser demonstration (not shared with other users)'}</span></div>${badge(state.live?'Approved':'Draft')}</div>${state.live?`<div class="setting-row"><div><strong>Authenticated user</strong><span>${esc(state.user.email)}</span></div></div><div class="setting-row"><div><strong>Assigned role</strong><span>Role is checked against Firestore roles collection</span></div><strong>${state.role==='reviewer'?'Risk Team':'Staff'}</strong></div><button class="btn" id="signOut">Sign out</button>`:`<div class="setting-row"><div><strong>Switch demo role</strong><span>For testing the workflow only; not production authentication.</span></div><select id="demoRole" class="form-control inline-select"><option value="staff" ${state.role==='staff'?'selected':''}>MRANTI Staff</option><option value="reviewer" ${state.role==='reviewer'?'selected':''}>Risk Team Reviewer</option></select></div><div class="setting-row"><div><strong>Reset demonstration data</strong><span>Restore the original fictitious risk examples</span></div><button class="btn danger small" id="resetDemo">Reset</button></div><div class="setting-row"><div><strong>Import CSV (demo only)</strong><span>Use the included sample-risk-import.csv template</span></div><button class="btn small" id="importCsv">Import CSV</button></div>`}</div></section><section class="panel"><div class="panel-head"><h2>Approval & Risk Policy</h2></div><div class="panel-body"><ol class="help-list"><li>Staff saves a draft or submits a new risk.</li><li>Risk Team starts the validation review.</li><li>Risk Team approves or returns the proposed plan with remarks.</li><li>Staff updates approved actions and progress.</li><li>Risk Team closes the risk after all actions are completed.</li></ol><div class="notice warning" style="margin:14px 0 0">Production approval rights must be controlled by authenticated accounts and server-side rules, not the demo role switch.</div></div></section></div><section class="panel"><div class="panel-head"><h2>Risk methodology & source</h2></div><div class="panel-body"><p class="subtitle">The layout follows the uploaded workbook fields: Ref. No, Risk Category, Title, Description, Root Cause, Consequences, Division / Department, Owner, Inherent Assessment, Response Strategy, Existing Controls, Control Effectiveness, Residual Assessment, Additional Controls, Action Status, Progress Updates and Dates.</p><p class="subtitle">Risk classifications are based on the workbook's <strong>Risk Assessment_Guide</strong>. Actual records from the confidential workbook are not embedded in this public-facing demo.</p></div></section>`;}
function render(){nav();const content=$('#content');const screens={dashboard,register,new:riskForm,approvals,actions:actionTracker,matrix,settings};content.innerHTML=(screens[state.view]||dashboard)();if(state.view==='new')riskScorePreview();}
function setView(v){if(v==='approvals'&&state.role!=='reviewer')v='dashboard';if(v==='new'){state.editingId=null;state.draftActions=[{id:uid(),description:'',owner:'',dueDate:'',status:'Not Started',progress:0,update:''}];}state.view=v;state.query='';state.filterLevel='';state.filterStatus='';closeDrawer();render();scrollTo({top:0,behavior:'instant'});}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),4300);}
async function persist(r){try{if(state.live) await state.backend.save(r);else{const idx=state.risks.findIndex(x=>x.id===r.id);if(idx<0)state.risks.unshift(r);else state.risks[idx]=r;localStorage.setItem(storageKey,JSON.stringify(state.risks));}if(state.live)await refreshLive();return true;}catch(err){console.error(err);toast('Unable to save: '+(err?.message||'permission or network error'),true);return false;}}
function findRisk(id){return visible().find(r=>r.id===id);}
function canEdit(r){return state.role==='staff'&&r.ownerUid===state.user.uid&&['Draft','Returned'].includes(r.status);}
function canMonitor(r){return state.role==='staff'&&r.ownerUid===state.user.uid&&['Approved','Monitoring'].includes(r.status);}
function canReview(r){return state.role==='reviewer'&&r.ownerUid!==state.user.uid&&['Submitted','Under Review'].includes(r.status);}
function field(label,value,wide=false){return `<div class="${wide?'wide':''}"><div class="detail-key">${esc(label)}</div><div class="detail-val">${esc(value||'—')}</div></div>`;}
function drawer(r){const s=riskScore(r.residualLikelihood,r.residualImpact);const inc=riskScore(r.inherentLikelihood,r.inherentImpact);const actions=r.actions||[];const monitor=canMonitor(r);const review=canReview(r);return `<div class="drawer-overlay"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Risk ${esc(r.id)}"><div class="drawer-head"><div><div class="ref">${esc(r.id)} ${badge(r.status)}</div><div class="drawer-title">${esc(r.title)}</div><p class="subtitle">${esc(r.division)} / ${esc(r.department)} · ${esc(r.ownerName)}</p></div><button class="close" aria-label="Close details" id="closeDrawer">×</button></div><div class="drawer-content"><section class="drawer-section"><h3>Risk Assessment</h3><div class="detail-grid">${field('Category',r.category)}${field('Risk response',r.response)}${field('Inherent / gross risk',`${inc} · ${riskLevel(inc)} (${listLike[r.inherentLikelihood-1]} × ${listImpact[r.inherentImpact-1]})`)}${field('Residual risk',`${s} · ${riskLevel(s)} (${listLike[r.residualLikelihood-1]} × ${listImpact[r.residualImpact-1]})`)}${field('Description',r.description,true)}${field('Root cause',r.rootCause,true)}${field('Consequences',r.consequences,true)}${field('Current controls',r.existingControls,true)}${field('Control effectiveness',r.controlEffectiveness)}</div></section><section class="drawer-section"><h3>Action Plan & Monitoring</h3>${actions.map((a,i)=>`<div class="action-monitor" data-monitor-row="${i}"><strong>${i+1}. ${esc(a.description)}</strong><small>Owner: ${esc(a.owner)} · Due: ${humanDate(a.dueDate)}</small><div class="progress-track"><div class="progress-fill" style="width:${n(a.progress,0)}%"></div></div>${monitor?`<div class="action-control-row"><div class="field"><label>Status</label><select class="form-control" data-monitor-field="status">${options(['Not Started','In Progress','Completed','Blocked'],a.status)}</select></div><div class="field"><label>Progress (%)</label><input class="form-control" data-monitor-field="progress" type="number" min="0" max="100" value="${n(a.progress,0)}"/></div></div><div class="field" style="margin-top:12px"><label>Progress update / evidence reference</label><textarea class="form-control" data-monitor-field="update" placeholder="Summary, document ID or link">${esc(a.update)}</textarea></div>`:`<small>Status: <strong>${esc(a.status)}</strong> · ${n(a.progress,0)}% completed</small>${a.update?`<div class="detail-val">${esc(a.update)}</div>`:''}`}</div>`).join('')}${monitor?'<button class="btn primary" id="saveMonitor" style="margin-top:13px">Save Action Progress</button>':''}${canEdit(r)?`<button class="btn primary" data-edit="${esc(r.id)}" style="margin-top:15px">✎ Edit & Resubmit</button>`:''}</section>${review?`<section class="drawer-section"><h3>Risk Team Validation</h3><form id="reviewForm" class="drawer-controls"><div class="notice warning">Validate the assessment and mitigation plan before approval. Any changes to scores will be captured in the record history.</div><div class="action-control-row"><div class="field"><label>Inherent likelihood</label><select class="form-control" name="inherentLikelihood">${scaleOptions(listLike,r.inherentLikelihood)}</select></div><div class="field"><label>Inherent impact</label><select class="form-control" name="inherentImpact">${scaleOptions(listImpact,r.inherentImpact)}</select></div><div class="field"><label>Residual likelihood</label><select class="form-control" name="residualLikelihood">${scaleOptions(listLike,r.residualLikelihood)}</select></div><div class="field"><label>Residual impact</label><select class="form-control" name="residualImpact">${scaleOptions(listImpact,r.residualImpact)}</select></div></div><div class="field" style="margin:14px 0"><label>Validation remarks / return reason</label><textarea class="form-control" name="reviewComment" placeholder="Record decision notes...">${esc(r.reviewComment)}</textarea></div><div class="actions"><button type="submit" name="reviewAction" value="Approved" class="btn primary">✓ Approve Plan</button><button type="submit" name="reviewAction" value="Returned" class="btn danger">↶ Return for Changes</button>${r.status==='Submitted'?'<button type="submit" name="reviewAction" value="Under Review" class="btn">Start Review</button>':''}</div></form></section>`:''}${state.role==='reviewer'&&r.ownerUid!==state.user.uid&&['Approved','Monitoring'].includes(r.status)?`<section class="drawer-section"><h3>Risk Closure</h3><div class="notice">Risk closure is separate from action-plan approval. All mitigation actions must be marked Completed.</div><button id="closeRisk" class="btn primary" ${actions.every(a=>a.status==='Completed')&&actions.length?'':'disabled'}>✓ Close This Risk</button></section>`:''}${r.reviewComment?`<section class="drawer-section"><h3>Latest Risk Team Remarks</h3><div class="notice">${esc(r.reviewComment)}</div></section>`:''}<section class="drawer-section"><h3>Activity Timeline</h3><div class="timeline">${[...(r.history||[])].reverse().map(h=>`<div class="timeline-item"><strong>${esc(h.action)}</strong><span>${esc(h.by)} · ${humanDate(h.at)}</span>${h.note?`<p>${esc(h.note)}</p>`:''}</div>`).join('')||'<p class="subtitle">No local history yet.</p>'}</div></section></div></aside></div>`;}
function showRisk(id){const r=findRisk(id);if(!r){toast('Risk not found or not accessible',true);return;}state.selectedId=id;$('#drawerHost').innerHTML=drawer(r);$('#closeDrawer')?.focus();}
function closeDrawer(){$('#drawerHost').innerHTML='';state.selectedId=null;}
async function saveForm(e){e.preventDefault();const f=e.target;const saveType=e.submitter?.value||'Submitted';syncActions();let actions=state.draftActions.map(a=>({...a,description:a.description.trim(),owner:a.owner.trim(),dueDate:a.dueDate}));if(saveType==='Submitted'&&actions.some(a=>!a.description||!a.owner||!a.dueDate)){toast('Complete every action description, owner and deadline.',true);return;}
 const data=Object.fromEntries(new FormData(f).entries());delete data.saveType;
 const old=state.editingId?state.risks.find(x=>x.id===state.editingId):null;
 if(old&&!canEdit(old)){toast('Only the risk owner may amend a draft or returned risk.',true);return;}
 const r={...old,...data,id:old?.id||`MRT-${year}-${uid().replaceAll('-','').slice(0,7).toUpperCase()}`,ownerUid:old?.ownerUid||state.user.uid,ownerEmail:old?.ownerEmail||state.user.email,inherentLikelihood:n(data.inherentLikelihood),inherentImpact:n(data.inherentImpact),residualLikelihood:n(data.residualLikelihood),residualImpact:n(data.residualImpact),actions,status:saveType,createdAt:old?.createdAt||stamp(),reviewBy:old?.reviewBy||'',reviewedAt:old?.reviewedAt||'',reviewComment:old?.reviewComment||'',history:old?.history||[]};
 history(r,saveType==='Draft'?'Saved risk draft':old?.status==='Returned'?'Resubmitted amended risk':'Submitted risk',`Risk score ${riskScore(r.residualLikelihood,r.residualImpact)} · ${riskLevel(riskScore(r.residualLikelihood,r.residualImpact))}`);
 if(await persist(r)){toast(saveType==='Draft'?'Risk saved as draft.':'Risk submitted for Risk Team validation.');state.editingId=null;setView('register');}
}
async function reviewForm(e){e.preventDefault();const action=e.submitter?.value;const old=state.risks.find(r=>r.id===state.selectedId);if(!old||!canReview(old))return toast('Not authorised to review this risk.',true);const data=Object.fromEntries(new FormData(e.target).entries());const remark=String(data.reviewComment||'').trim();if(action==='Returned'&&!remark){toast('Please provide a reason for returning the risk.',true);return;}
 if(action==='Approved'&&(!old.actions?.length||old.actions.some(a=>!a.description||!a.owner||!a.dueDate))){toast('An approval requires a complete action plan.',true);return;}
 const r={...old,status:action,reviewComment:remark,reviewBy:state.user.name,reviewedAt:stamp(),inherentLikelihood:n(data.inherentLikelihood),inherentImpact:n(data.inherentImpact),residualLikelihood:n(data.residualLikelihood),residualImpact:n(data.residualImpact)};
 history(r,action==='Approved'?'Approved action plan':action==='Returned'?'Returned for changes':'Review started',remark);
 if(await persist(r)){toast(action==='Approved'?'Action plan approved.':action==='Returned'?'Risk returned to risk owner.':'Risk marked Under Review.');closeDrawer();render();}
}
async function monitor(){const old=state.risks.find(r=>r.id===state.selectedId);if(!old||!canMonitor(old))return toast('Not authorised to update these actions.',true);let valid=true;const actions=old.actions.map((a,i)=>{const el=$(`[data-monitor-row="${i}"]`);const progress=Number(el.querySelector('[data-monitor-field="progress"]').value);const status=el.querySelector('[data-monitor-field="status"]').value;if(!Number.isFinite(progress)||progress<0||progress>100){valid=false;return a;}return {...a,status,progress:status==='Completed'?100:progress,update:el.querySelector('[data-monitor-field="update"]').value.trim()};});if(!valid){toast('Progress must be between 0 and 100.',true);return;}const r={...old,actions,status:'Monitoring'};history(r,'Updated action progress',`Progress: ${actions.map(a=>a.progress+'%').join(', ')}`);if(await persist(r)){toast('Action monitoring updated.');render();showRisk(r.id);}}
async function closeRisk(){const old=state.risks.find(r=>r.id===state.selectedId);if(state.role!=='reviewer'||!old||old.ownerUid===state.user.uid||!['Approved','Monitoring'].includes(old.status)||!old.actions?.length||old.actions.some(a=>a.status!=='Completed'))return toast('Risk closure requires all actions to be completed.',true);const r={...old,status:'Closed',reviewBy:state.user.name,reviewedAt:stamp()};history(r,'Risk closed','All mitigation actions confirmed completed.');if(await persist(r)){toast('Risk closed by Risk Team.');closeDrawer();render();}}
const csvColumns=['id','title','category','division','department','ownerName','status','inherentLikelihood','inherentImpact','residualLikelihood','residualImpact','response','existingControls','controlEffectiveness','rootCause','consequences','description','reviewComment','actions'];
function csvCell(v){const s=String(v??'');return /[",\r\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s;}
function exportCSV(){const content='\ufeff'+[csvColumns.join(','),...visible().map(r=>csvColumns.map(k=>csvCell(k==='actions'?JSON.stringify(r.actions||[]):r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`MRANTI-RiskHub-${today()}.csv`;a.click();URL.revokeObjectURL(url);toast('CSV exported. Handle this file as internal MRANTI data.');}
function parseCsv(src){const rows=[];let cell='',row=[],inside=false;for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(inside&&src[i+1]==='"'){cell+='"';i++;}else inside=!inside;}else if(c===','&&!inside){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!inside){if(c==='\r'&&src[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.length))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(x=>x.length))rows.push(row);return rows;}
async function importCSV(file){if(state.live||state.role!=='reviewer'){toast('Bulk import is for offline demonstration only. Production needs a managed migration.',true);return;}const raw=await file.text(),rows=parseCsv(raw.replace(/^\ufeff/,''));if(rows.length<2)return toast('CSV contains no data rows.',true);const keys=rows.shift().map(s=>s.trim());if(!['title','category','division','department','description'].every(x=>keys.includes(x)))return toast('CSV is missing required headers. See sample-risk-import.csv.',true);let c=0;for(const cols of rows){const x=Object.fromEntries(keys.map((k,i)=>[k,cols[i]||'']));const o={...emptyForm,...x};const a={id:uid(),description:x.actionPlan||'To be defined during review',owner:x.actionOwner||x.ownerName||'Unassigned',dueDate:x.dueDate||'',status:'Not Started',progress:0,update:''};const r={...o,id:x.id||`MRT-${year}-${uid().slice(0,7)}`,ownerUid:demoReviewer.uid,ownerEmail:demoReviewer.email,ownerName:x.ownerName||demoReviewer.name,status:'Draft',actions:[a],inherentLikelihood:Math.max(1,Math.min(5,n(x.inherentLikelihood,3))),inherentImpact:Math.max(1,Math.min(5,n(x.inherentImpact,3))),residualLikelihood:Math.max(1,Math.min(5,n(x.residualLikelihood,2))),residualImpact:Math.max(1,Math.min(5,n(x.residualImpact,2))),createdAt:stamp(),updatedAt:stamp(),history:[],reviewComment:'',reviewBy:'',reviewedAt:''};if(state.risks.some(z=>z.id===r.id))continue;history(r,'Imported CSV risk','Demo-only draft; validate before use.');state.risks.push(r);c++;}localStorage.setItem(storageKey,JSON.stringify(state.risks));toast(`Imported ${c} draft risk(s) into browser demonstration.`);render();}
async function refreshLive(){if(state.live){state.risks=await state.backend.list();}}
function bindEvents(){document.addEventListener('click',async e=>{const v=e.target.closest('[data-view]');if(v){setView(v.dataset.view);return;}const r=e.target.closest('[data-risk]');if(r){showRisk(r.dataset.risk);return;}const ed=e.target.closest('[data-edit]');if(ed){const old=state.risks.find(x=>x.id===ed.dataset.edit);if(!old||!canEdit(old))return;state.editingId=old.id;state.draftActions=structuredClone(old.actions||[]);state.view='new';closeDrawer();render();scrollTo(0,0);return;}if(e.target.closest('#closeDrawer')||e.target.classList.contains('drawer-overlay')){closeDrawer();return;}const add=e.target.closest('#addAction');if(add){syncActions();state.draftActions.push({id:uid(),description:'',owner:'',dueDate:'',status:'Not Started',progress:0,update:''});renderFormActions();return;}const remove=e.target.closest('[data-remove-action]');if(remove){syncActions();state.draftActions.splice(Number(remove.dataset.removeAction),1);renderFormActions();return;}if(e.target.closest('#saveMonitor')){await monitor();return;}if(e.target.closest('#closeRisk')){await closeRisk();return;}if(e.target.closest('#exportCsv')){exportCSV();return;}if(e.target.closest('#resetDemo')){if(!confirm('Restore sample records? Browser-only changes will be discarded.'))return;localStorage.removeItem(storageKey);state.risks=structuredClone(seed);render();toast('Demo data has been restored.');return;}if(e.target.closest('#importCsv')){$('#csvUpload').click();return;}if(e.target.closest('#signOut')){await state.backend?.signOut();state.user=null;renderLogin();return;}if(e.target.closest('#mobileMenu')){$('.sidebar').classList.toggle('mobile-open');return;}if(v||r)$('.sidebar').classList.remove('mobile-open');});
 document.addEventListener('submit',async e=>{if(e.target.id==='riskForm')await saveForm(e);else if(e.target.id==='reviewForm')await reviewForm(e);});
 document.addEventListener('change',e=>{if(e.target.matches('#demoRole')){state.role=e.target.value;state.user=state.role==='reviewer'?demoReviewer:demoStaff;setView('dashboard');toast('Demo role switched. In production roles are assigned by an administrator.');}else if(e.target.matches('#statusFilter')){state.filterStatus=e.target.value;render();}else if(e.target.matches('#levelFilter')){state.filterLevel=e.target.value;render();}else if(e.target.closest('#riskForm')&&['inherentLikelihood','inherentImpact','residualLikelihood','residualImpact'].includes(e.target.name)){riskScorePreview();}});
 document.addEventListener('input',e=>{if(e.target.matches('#searchRisk')){const pos=e.target.selectionStart;state.query=e.target.value;$('#riskRows').innerHTML=table(visible().filter(r=>(!state.filterStatus||r.status===state.filterStatus)&&(!state.filterLevel||riskLevel(riskScore(r.residualLikelihood,r.residualImpact))===state.filterLevel)&&[r.title,r.id,r.division,r.department,r.category,r.ownerName].join(' ').toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)));e.target.setSelectionRange(pos,pos);}});
 $('#csvUpload').addEventListener('change',async e=>{if(e.target.files[0])await importCSV(e.target.files[0]);e.target.value='';});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();});}
function renderLogin(error=''){nav();$('#content').innerHTML=`<div class="login-screen"><div class="login-box"><div class="login-mark">M</div><h1>Welcome to MRANTI RiskHub</h1><p class="subtitle">Use your authorised MRANTI Google Workspace account to access the enterprise risk register.</p>${error?`<div class="notice warning">${esc(error)}</div>`:''}<button id="loginGoogle" class="btn primary">Sign in with Google Workspace →</button><p class="hint">Only verified @mranti.my accounts are permitted. Risk Team rights are assigned separately.</p></div></div>`;$('#loginGoogle').addEventListener('click',async()=>{try{await state.backend.signIn();await enterLive();}catch(e){renderLogin(e.message);}});}
async function enterLive(){const user=await state.backend.currentUser();if(!user){renderLogin();return;}if(!user.email?.toLowerCase().endsWith('@mranti.my')||!user.emailVerified){await state.backend.signOut();renderLogin('Only verified @mranti.my accounts are allowed.');return;}state.user={uid:user.uid,name:user.displayName||user.email,email:user.email};const role=await state.backend.role(user.uid);state.role=role==='reviewer'?'reviewer':'staff';await refreshLive();state.view='dashboard';render();}
async function init(){bindEvents();if(window.RISKHUB_FIREBASE_CONFIG?.projectId){try{const m=await import('./firebase-adapter.js');state.backend=await m.initialize(window.RISKHUB_FIREBASE_CONFIG);state.live=true;const user=await state.backend.currentUser();if(user)await enterLive();else renderLogin();}catch(e){console.error(e);state.live=true;state.user={name:'Guest',email:'',uid:''};renderLogin(`Unable to initialise Firebase: ${e.message}`);}}else{try{const saved=JSON.parse(localStorage.getItem(storageKey));state.risks=Array.isArray(saved)?saved:structuredClone(seed);}catch{state.risks=structuredClone(seed);}state.draftActions=[{id:uid(),description:'',owner:'',dueDate:'',status:'Not Started',progress:0,update:''}];render();}}
init();
